object StaticCreatureCatalog {

    private fun sprite(id: Int): String {
        return "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/$id.png"
    }

    private fun c(
        id: Int,
        name: String,
        category: String,
        pType: String,
        sType: String?,
        rarity: String,
        height: Double,
        weight: Double,
        hp: Int,
        atk: Int,
        def: Int,
        spd: Int,
        catchRate: Double,
        fleeRate: Double,
        desc: String
    ): CreatureEntity {
        return CreatureEntity(
            id = id,
            name = name,
            category = category,
            primaryType = pType,
            secondaryType = sType,
            rarityCode = rarity,
            heightMeters = height,
            weightKg = weight,
            hp = hp,
            attack = atk,
            defense = def,
            speed = spd,
            baseCaptureRate = catchRate,
            fleeRate = fleeRate,
            spriteUrl = sprite(id),
            description = desc
        )
    }

