    fun toDomain(entity: CreatureEntity): Creature {
        return Creature(
            id = entity.id,
            name = entity.name,
            category = entity.category,
            primaryType = CreatureType.fromString(entity.primaryType),
            secondaryType = entity.secondaryType?.let { CreatureType.fromString(it) },
            rarity = Rarity.fromCode(entity.rarityCode),
            heightMeters = entity.heightMeters,
            weightKg = entity.weightKg,
            hp = entity.hp,
            attack = entity.attack,
            defense = entity.defense,
            speed = entity.speed,
            baseCaptureRate = entity.baseCaptureRate,
            fleeRate = entity.fleeRate,
            spriteUrl = entity.spriteUrl,
            description = entity.description
        )
    }
}
